enum class Trust {
    
    /**
     * Not paired: the connection is refused.
     */
    UNKNOWN,
    /**
     * QR-paired: transfers need the user's approval, clipboard is allowed.
     */
    PAIRED,
    /**
     * QR-paired as one of the user's own devices: transfers are auto-accepted.
     */
    OWN;

    


    companion object
}


